  ($seed$interface$seed$, $seed$PC817 Phototransistor optocoupler$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"Anode","x":0,"y":20,"type":"input"},{"id":"p2","name":"Cathode","x":0,"y":40,"type":"input"},{"id":"p3","name":"Emitter","x":160,"y":20,"type":"output"},{"id":"p4","name":"Collector","x":160,"y":40,"type":"output"}]$json$, $json${"type":"PC817","voltage":"5V","rating":"5 kVrms isolation; VCEO 80 V; CTR 50–400 %","package":"DIP-4","footprint":"DIP-4"}$json$, null, $seed$LED on 1/2 drives a phototransistor on 3/4; the classic way to break a ground loop around a feedback pin.$seed$, $seed$Vishay$seed$, $seed$PC817$seed$, $seed$https://www.vishay.com/docs/84100/pc817.pdf$seed$, $json$["optocoupler","dip-4","pc817"]$json$),
