  ($seed$interface$seed$, $seed$ULN2003A Seven 500 mA Darlington driver array$seed$, true, $json${"width":160,"height":180,"paths":["M 0,0 L 160,0 L 160,180 L 0,180 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"1B","x":0,"y":20,"type":"input"},{"id":"p2","name":"2B","x":0,"y":40,"type":"input"},{"id":"p3","name":"3B","x":0,"y":60,"type":"input"},{"id":"p4","name":"4B","x":0,"y":80,"type":"input"},{"id":"p5","name":"5B","x":0,"y":100,"type":"input"},{"id":"p6","name":"6B","x":0,"y":120,"type":"input"},{"id":"p7","name":"7B","x":0,"y":140,"type":"input"},{"id":"p8","name":"GND","x":0,"y":160,"type":"ground"},{"id":"p9","name":"COM","x":160,"y":20,"type":"passive"},{"id":"p10","name":"7C","x":160,"y":40,"type":"output"},{"id":"p11","name":"6C","x":160,"y":60,"type":"output"},{"id":"p12","name":"5C","x":160,"y":80,"type":"output"},{"id":"p13","name":"4C","x":160,"y":100,"type":"output"},{"id":"p14","name":"3C","x":160,"y":120,"type":"output"},{"id":"p15","name":"2C","x":160,"y":140,"type":"output"},{"id":"p16","name":"1C","x":160,"y":160,"type":"output"}]$json$, $json${"type":"ULN2003A","voltage":"5V","rating":"VCEO 50 V; 500 mA per output; free-wheeling diodes to COM","package":"DIP-16","footprint":"DIP-16"}$json$, null, $seed$Logic-level inputs sink relay coils and stepper phases; outputs are numbered opposite the inputs, and COM clamps the flyback.$seed$, $seed$STMicroelectronics$seed$, $seed$ULN2003A$seed$, $seed$https://www.st.com/resource/en/datasheet/uln2003a.pdf$seed$, $json$["driver-array","dip-16","uln2003a"]$json$),
  ($seed$semiconductor$seed$, $seed$TIP120 NPN Darlington transistor 60 V$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"BASE","x":0,"y":20,"type":"input"},{"id":"p2","name":"COLLECTOR","x":0,"y":40,"type":"passive"},{"id":"p3","name":"EMITTER","x":160,"y":20,"type":"passive"}]$json$, $json${"type":"TIP120","voltage":"60V","rating":"V(BR)CBO 60 V; 5 A continuous; hFE ~1000","package":"TO-220-3","footprint":"TO-220-3"}$json$, null, $seed$Darlington switch for loads a GPIO cannot drive: base on 1, collector on 2, emitter on 3.$seed$, $seed$onsemi$seed$, $seed$TIP120$seed$, $seed$https://www.onsemi.com/download/data-sheet/pdf/tip120-d.pdf$seed$, $json$["bipolar-transistor","to-220-3","tip120"]$json$),
  ($seed$semiconductor$seed$, $seed$BSS138 N-channel MOSFET 50 V SOT-23$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"GATE","x":0,"y":20,"type":"input"},{"id":"p2","name":"SOURCE","x":0,"y":40,"type":"passive"},{"id":"p3","name":"DRAIN","x":160,"y":20,"type":"passive"}]$json$, $json${"type":"BSS138","voltage":"50V","rating":"50 V VDS; 0.22 A; logic-level gate","package":"SOT-23","footprint":"SOT-23"}$json$, null, $seed$Small-signal N-FET for open-drain level shifting; gate on 1, source on 2, drain on 3.$seed$, $seed$onsemi$seed$, $seed$BSS138$seed$, $seed$https://www.onsemi.com/download/data-sheet/pdf/bss138-d.pdf$seed$, $json$["mosfet","sot-23","bss138"]$json$),
  ($seed$interface$seed$, $seed$ISO7741DW Quad-channel digital isolator, 3 forward + 1 reverse$seed$, true, $json${"width":160,"height":180,"paths":["M 0,0 L 160,0 L 160,180 L 0,180 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"VCC1","x":0,"y":20,"type":"power"},{"id":"p2","name":"GND1","x":0,"y":40,"type":"ground"},{"id":"p3","name":"INA","x":0,"y":60,"type":"input"},{"id":"p4","name":"INB","x":0,"y":80,"type":"input"},{"id":"p5","name":"INC","x":0,"y":100,"type":"input"},{"id":"p6","name":"OUTD","x":0,"y":120,"type":"output"},{"id":"p7","name":"EN1","x":0,"y":140,"type":"input"},{"id":"p8","name":"GND1","x":0,"y":160,"type":"ground"},{"id":"p9","name":"GND2","x":160,"y":20,"type":"ground"},{"id":"p10","name":"EN2","x":160,"y":40,"type":"input"},{"id":"p11","name":"IND","x":160,"y":60,"type":"input"},{"id":"p12","name":"OUTC","x":160,"y":80,"type":"output"},{"id":"p13","name":"OUTB","x":160,"y":100,"type":"output"},{"id":"p14","name":"OUTA","x":160,"y":120,"type":"output"},{"id":"p15","name":"GND2","x":160,"y":140,"type":"ground"},{"id":"p16","name":"VCC2","x":160,"y":160,"type":"power"}]$json$, $json${"type":"ISO7741DW","voltage":"2.25 V to 5.5 V on each side","rating":"Up to 5000 VRMS isolation and 12.8 kV surge, 100 Mbps, 10.7 ns typical delay at 5 V, 100 kV/us CMTI","package":"SOIC-16 (DW, 10.30 x 7.50 mm) / SSOP-16 (DBQ, 4.90 x 3.90 mm)","footprint":"SOIC-16"}$json$, null, $seed$Four isolated logic channels with VCC1/GND1 driving INA, INB and INC and VCC2/GND2 driving OUTA, OUTB, OUTC plus the reverse IND to OUTD. EN1 and EN2 hold their side disabled; the default output is high.$seed$, $seed$Texas Instruments$seed$, $seed$ISO7741DW$seed$, $seed$https://www.ti.com/lit/ds/symlink/iso7741.pdf$seed$, $json$["digital-isolator","soic-16 (dw, 10.30 x 7.50 mm) / ssop-16 (dbq, 4.90 x 3.90 mm)","iso7741dw"]$json$),
  ($seed$interface$seed$, $seed$TXB0104 4-bit bidirectional level translator$seed$, true, $json${"width":160,"height":160,"paths":["M 0,0 L 160,0 L 160,160 L 0,160 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"VCCA","x":0,"y":20,"type":"power"},{"id":"p2","name":"A1","x":0,"y":40,"type":"io"},{"id":"p3","name":"A2","x":0,"y":60,"type":"io"},{"id":"p4","name":"A3","x":0,"y":80,"type":"io"},{"id":"p5","name":"A4","x":0,"y":100,"type":"io"},{"id":"p6","name":"NC","x":0,"y":120,"type":"passive"},{"id":"p7","name":"GND","x":0,"y":140,"type":"ground"},{"id":"p8","name":"OE","x":160,"y":20,"type":"input"},{"id":"p9","name":"NC","x":160,"y":40,"type":"passive"},{"id":"p10","name":"B4","x":160,"y":60,"type":"io"},{"id":"p11","name":"B3","x":160,"y":80,"type":"io"},{"id":"p12","name":"B2","x":160,"y":100,"type":"io"},{"id":"p13","name":"B1","x":160,"y":120,"type":"io"},{"id":"p14","name":"VCCB","x":160,"y":140,"type":"power"}]$json$, $json${"type":"TXB0104","voltage":"VCCA 1.2 V to 3.6 V; VCCB 1.65 V to 5.5 V (VCCA must not exceed VCCB)","rating":"Automatic direction sensing, ±15 kV HBM on the B port, 5 µA max ICC, VCC isolation puts all outputs high-impedance if either rail is at ground","package":"SOIC-14 (D) / TSSOP-14 (PW)","footprint":"SOIC-14"}$json$, null, $seed$Non-inverting four-bit translator between any of the 1.2, 1.5, 1.8, 2.5, 3.3 and 5 V nodes. Pins 6 and 9 are no-connect; OE sits on 8, is referenced to VCCA and needs a pull-down to stay off during power-up.$seed$, $seed$Texas Instruments$seed$, $seed$TXB0104$seed$, $seed$https://www.ti.com/lit/ds/symlink/txb0104.pdf$seed$, $json$["level-translator","soic-14 (d) / tssop-14 (pw)","txb0104"]$json$),
  ($seed$interface$seed$, $seed$PCA9306 2-bit I2C bus level translator$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"GND","x":0,"y":20,"type":"ground"},{"id":"p2","name":"VREF1","x":0,"y":40,"type":"power"},{"id":"p3","name":"SCL1","x":0,"y":60,"type":"io"},{"id":"p4","name":"SDA1","x":0,"y":80,"type":"io"},{"id":"p5","name":"SDA2","x":160,"y":20,"type":"io"},{"id":"p6","name":"SCL2","x":160,"y":40,"type":"io"},{"id":"p7","name":"VREF2","x":160,"y":60,"type":"power"},{"id":"p8","name":"EN","x":160,"y":80,"type":"input"}]$json$, $json${"type":"PCA9306","voltage":"VREF1 1.2 V up to VREF2 - 0.6 V; VREF2 from VREF1 + 0.6 V up to 5.5 V (threshold about 0.6 V at room temperature)","rating":"Pass-switch topology with 64 mA max pass current, I/O rated 0 to 5.5 V, -40 to 85 C, ±2 kV HBM and ±1 kV CDM","package":"SSOP-8 (DCT) / VSSOP-8 (DCU) / X2SON-8 (DQE) / DSBGA-8 (YZT)","footprint":"SSOP-8"}$json$, null, $seed$The two switch pairs that join a 1.8 V MCU I2C bus to a 5 V device: side 1 on SCL1/SDA1, side 2 mirrored as SDA2/SCL2, each referenced to its own VREF pin and gated by EN on pin 8. The part supplies no drive of its own, so the bus pull-ups still set the rise time on both sides.$seed$, $seed$Texas Instruments$seed$, $seed$PCA9306$seed$, $seed$https://www.ti.com/lit/ds/symlink/pca9306.pdf$seed$, $json$["level-translator","ssop-8 (dct) / vssop-8 (dcu) / x2son-8 (dqe) / dsbga-8 (yzt)","pca9306"]$json$),
  ($seed$interface$seed$, $seed$LAN8720A 10/100 Ethernet PHY with RMII$seed$, true, $json${"width":160,"height":260,"paths":["M 0,0 L 160,0 L 160,260 L 0,260 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"VDD2A","x":0,"y":20,"type":"power"},{"id":"p2","name":"LED2/nINTSEL","x":0,"y":40,"type":"io"},{"id":"p3","name":"LED1/REGOFF","x":0,"y":60,"type":"io"},{"id":"p4","name":"XTAL2","x":0,"y":80,"type":"output"},{"id":"p5","name":"XTAL1/CLKIN","x":0,"y":100,"type":"input"},{"id":"p6","name":"VDDCR","x":0,"y":120,"type":"power"},{"id":"p7","name":"RXD1/MODE1","x":0,"y":140,"type":"io"},{"id":"p8","name":"RXD0/MODE0","x":0,"y":160,"type":"io"},{"id":"p9","name":"VDDIO","x":0,"y":180,"type":"power"},{"id":"p10","name":"RXER/PHYAD0","x":0,"y":200,"type":"io"},{"id":"p11","name":"CRS_DV/MODE2","x":0,"y":220,"type":"io"},{"id":"p12","name":"MDIO","x":0,"y":240,"type":"io"},{"id":"p13","name":"MDC","x":160,"y":20,"type":"input"},{"id":"p14","name":"nINT/REFCLKO","x":160,"y":40,"type":"output"},{"id":"p15","name":"nRST","x":160,"y":60,"type":"input"},{"id":"p16","name":"TXEN","x":160,"y":80,"type":"input"},{"id":"p17","name":"TXD0","x":160,"y":100,"type":"input"},{"id":"p18","name":"TXD1","x":160,"y":120,"type":"input"},{"id":"p19","name":"VDD1A","x":160,"y":140,"type":"power"},{"id":"p20","name":"TXN","x":160,"y":160,"type":"io"},{"id":"p21","name":"TXP","x":160,"y":180,"type":"io"},{"id":"p22","name":"RXN","x":160,"y":200,"type":"io"},{"id":"p23","name":"RXP","x":160,"y":220,"type":"io"},{"id":"p24","name":"RBIAS","x":160,"y":240,"type":"passive"}]$json$, $json${"type":"LAN8720A","voltage":"VDDIO 1.6-3.6 V; VDD1A and VDD2A 3.3 V analog; VDDCR 1.2 V from the on-chip regulator unless REGOFF is strapped","rating":"RBIAS needs a 12.1 kΩ 1 % resistor to ground (1.2 V nominal, about 1 mW); the digital signals are not 5 V tolerant; the exposed pad is VSS and must be grounded","package":"QFN-24 (4 x 4 x 0.85 mm) with exposed VSS pad","footprint":"QFN-24"}$json$, null, $seed$The PHY that turns an MCU RMII bus into a magnetics-coupled twisted pair: TXEN and TXD0/TXD1 are MAC inputs, RXD0/RXD1, RXER and CRS_DV are MAC outputs, MDIO/MDC carry the SMI register access, and the line-side pairs are analogue both ways. MODE0-MODE2 and PHYAD0 straps share the receive pins and latch at reset, so a load on those pins needs an external resistor.$seed$, $seed$Microchip Technology (SMSC)$seed$, $seed$LAN8720A$seed$, $seed$https://ww1.microchip.com/downloads/en/DeviceDoc/00002165B.pdf$seed$, $json$["ethernet-phy","qfn-24 (4 x 4 x 0.85 mm) with exposed vss pad","lan8720a"]$json$),
  ($seed$amplifier$seed$, $seed$LM358 Dual op-amp, single supply$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"OUT1","x":0,"y":20,"type":"output"},{"id":"p2","name":"IN1-","x":0,"y":40,"type":"input"},{"id":"p3","name":"IN1+","x":0,"y":60,"type":"input"},{"id":"p4","name":"V-","x":0,"y":80,"type":"ground"},{"id":"p5","name":"IN2+","x":160,"y":20,"type":"input"},{"id":"p6","name":"IN2-","x":160,"y":40,"type":"input"},{"id":"p7","name":"OUT2","x":160,"y":60,"type":"output"},{"id":"p8","name":"V+","x":160,"y":80,"type":"power"}]$json$, $json${"type":"LM358","family":"op-amp","supply":"3 V to 36 V","rating":"Two amplifiers in one 8-pin body; pin 4 is the lowest supply, so it runs single-supply","spice":"LM358","package":"SOIC-8 / PDIP-8","footprint":"SOIC-8"}$json$, null, $seed$The workhorse dual op-amp for sensor buffering and filtering on a single rail: OUT1/IN1 on pins 1-3, OUT2/IN2 on pins 5-7, supply across 4 and 8.$seed$, $seed$Texas Instruments$seed$, $seed$LM358$seed$, $seed$https://www.ti.com/lit/ds/symlink/lm358.pdf$seed$, $json$["op-amp","soic-8 / pdip-8","lm358"]$json$),
  ($seed$amplifier$seed$, $seed$TL072 Dual JFET-input op-amp$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"1OUT","x":0,"y":20,"type":"output"},{"id":"p2","name":"1IN-","x":0,"y":40,"type":"input"},{"id":"p3","name":"1IN+","x":0,"y":60,"type":"input"},{"id":"p4","name":"VCC-","x":0,"y":80,"type":"power"},{"id":"p5","name":"2IN+","x":160,"y":20,"type":"input"},{"id":"p6","name":"2IN-","x":160,"y":40,"type":"input"},{"id":"p7","name":"2OUT","x":160,"y":60,"type":"output"},{"id":"p8","name":"VCC+","x":160,"y":80,"type":"power"}]$json$, $json${"type":"TL072","family":"op-amp","supply":"Split rails, per the datasheet recommended-conditions table","rating":"JFET input, 1 mV typical offset, 20 V/µs slew rate","package":"SOIC-8 / PDIP-8","footprint":"SOIC-8"}$json$, null, $seed$Low-bias-current dual op-amp for audio and instrument front ends. Same pin order as the LM358 but with the rails labelled VCC-/VCC+ on pins 4 and 8.$seed$, $seed$Texas Instruments$seed$, $seed$TL072$seed$, $seed$https://www.ti.com/lit/ds/symlink/tl072.pdf$seed$, $json$["op-amp","soic-8 / pdip-8","tl072"]$json$),
  ($seed$amplifier$seed$, $seed$OPA2134 Dual soundPlus audio op-amp$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"OUT A","x":0,"y":20,"type":"output"},{"id":"p2","name":"-IN A","x":0,"y":40,"type":"input"},{"id":"p3","name":"+IN A","x":0,"y":60,"type":"input"},{"id":"p4","name":"V-","x":0,"y":80,"type":"ground"},{"id":"p5","name":"+IN B","x":160,"y":20,"type":"input"},{"id":"p6","name":"-IN B","x":160,"y":40,"type":"input"},{"id":"p7","name":"OUT B","x":160,"y":60,"type":"output"},{"id":"p8","name":"V+","x":160,"y":80,"type":"power"}]$json$, $json${"type":"OPA2134","family":"op-amp","supply":"(V+) − (V−) up to 36 V","rating":"Channel A on pins 1-3, channel B mirrored on 5-7, rails on 4 and 8","package":"SOIC-8 / PDIP-8","footprint":"SOIC-8"}$json$, null, $seed$Low-noise, low-distortion dual bipolar op-amp used in line-level audio stages and precision buffers.$seed$, $seed$Texas Instruments$seed$, $seed$OPA2134$seed$, $seed$https://www.ti.com/lit/ds/symlink/opa2134.pdf$seed$, $json$["op-amp","soic-8 / pdip-8","opa2134"]$json$),
  ($seed$amplifier$seed$, $seed$OPA2188 Zero-drift dual op-amp$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"OUT A","x":0,"y":20,"type":"output"},{"id":"p2","name":"-IN A","x":0,"y":40,"type":"input"},{"id":"p3","name":"+IN A","x":0,"y":60,"type":"input"},{"id":"p4","name":"V-","x":0,"y":80,"type":"ground"},{"id":"p5","name":"+IN B","x":160,"y":20,"type":"input"},{"id":"p6","name":"-IN B","x":160,"y":40,"type":"input"},{"id":"p7","name":"OUT B","x":160,"y":60,"type":"output"},{"id":"p8","name":"V+","x":160,"y":80,"type":"power"}]$json$, $json${"type":"OPA2188","family":"op-amp","supply":"4 V to 36 V total (±2 V to ±18 V)","rating":"25 µV max offset, 0.03 µV/°C drift, 2 MHz gain bandwidth","package":"VSSOP-8 (DGK) / SO-8 (D)","footprint":"VSSOP-8"}$json$, null, $seed$Chopper-stabilised dual op-amp for DC-coupled measurement: inputs include the negative rail and the output swings rail-to-rail.$seed$, $seed$Texas Instruments$seed$, $seed$OPA2188$seed$, $seed$https://www.ti.com/lit/ds/symlink/opa2188.pdf$seed$, $json$["op-amp","vssop-8 (dgk) / so-8 (d)","opa2188"]$json$),
  ($seed$amplifier$seed$, $seed$ADA4528-2 Zero-drift dual op-amp 2.2-5.5 V$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"OUT A","x":0,"y":20,"type":"output"},{"id":"p2","name":"-IN A","x":0,"y":40,"type":"input"},{"id":"p3","name":"+IN A","x":0,"y":60,"type":"input"},{"id":"p4","name":"V-","x":0,"y":80,"type":"ground"},{"id":"p5","name":"+IN B","x":160,"y":20,"type":"input"},{"id":"p6","name":"-IN B","x":160,"y":40,"type":"input"},{"id":"p7","name":"OUT B","x":160,"y":60,"type":"output"},{"id":"p8","name":"V+","x":160,"y":80,"type":"power"}]$json$, $json${"type":"ADA4528-2","family":"op-amp","supply":"2.2 V to 5.5 V (±1.1 V to ±2.75 V)","rating":"2.5 µV max offset, 0.015 µV/°C drift, 3 MHz bandwidth at gain 100","package":"MSOP-8 (RM) / LFCSP-8 (CP)","footprint":"MSOP-8"}$json$, null, $seed$Low-voltage zero-drift dual for 3.3 V and 5 V sensor paths. There is no SO-8 option, so the footprint is MSOP or LFCSP; the LFCSP adds an exposed pad.$seed$, $seed$Analog Devices$seed$, $seed$ADA4528-2$seed$, $seed$https://www.analog.com/media/en/technical-documentation/data-sheets/ADA4528-1_4528-2.pdf$seed$, $json$["op-amp","msop-8 (rm) / lfcsp-8 (cp)","ada4528-2"]$json$),
  ($seed$amplifier$seed$, $seed$INA128 Programmable-gain instrumentation amp$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"RG","x":0,"y":20,"type":"passive"},{"id":"p2","name":"VIN-","x":0,"y":40,"type":"input"},{"id":"p3","name":"VIN+","x":0,"y":60,"type":"input"},{"id":"p4","name":"V-","x":0,"y":80,"type":"ground"},{"id":"p5","name":"REF","x":160,"y":20,"type":"input"},{"id":"p6","name":"VO","x":160,"y":40,"type":"output"},{"id":"p7","name":"V+","x":160,"y":60,"type":"power"},{"id":"p8","name":"RG","x":160,"y":80,"type":"passive"}]$json$, $json${"type":"INA128","family":"instrumentation-amp","supply":"(V+) − (V−) up to 36 V","rating":"Gain = 1 + 50 kΩ/RG, the resistor sitting across pins 1 and 8","package":"SOIC-8 / PDIP-8","footprint":"SOIC-8"}$json$, null, $seed$Strain-gauge and thermocouple front end: differential inputs on 2/3, output on 6, reference on 5 sets the output centre, and one gain resistor across 1 and 8.$seed$, $seed$Texas Instruments$seed$, $seed$INA128$seed$, $seed$https://www.ti.com/lit/ds/symlink/ina128.pdf$seed$, $json$["instrumentation-amp","soic-8 / pdip-8","ina128"]$json$),
  ($seed$amplifier$seed$, $seed$INA180A1 Current-sense amplifier 20 V/V$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"OUT","x":0,"y":20,"type":"output"},{"id":"p2","name":"GND","x":0,"y":40,"type":"ground"},{"id":"p3","name":"IN+","x":0,"y":60,"type":"input"},{"id":"p4","name":"IN-","x":160,"y":20,"type":"input"},{"id":"p5","name":"VS","x":160,"y":40,"type":"power"}]$json$, $json${"type":"INA180A1","family":"current-sense-amp","supply":"2.7 V to 5.5 V","rating":"Fixed 20 V/V (A1 grade), common-mode −0.2 V to 26 V independent of supply","package":"SOT-23-5 (DBV)","footprint":"SOT-23-5"}$json$, null, $seed$Shunt-monitor amplifier for bus current telemetry. Pinout A (this table) is the A-grade part; the B-grade INA180B* ships a mirrored pinout, so check the suffix before landing a footprint.$seed$, $seed$Texas Instruments$seed$, $seed$INA180A1$seed$, $seed$https://www.ti.com/lit/ds/symlink/ina180.pdf$seed$, $json$["current-sense-amp","sot-23-5 (dbv)","ina180a1"]$json$),
  ($seed$amplifier$seed$, $seed$LM393 Dual comparator, open-collector$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"1OUT","x":0,"y":20,"type":"output"},{"id":"p2","name":"1IN-","x":0,"y":40,"type":"input"},{"id":"p3","name":"1IN+","x":0,"y":60,"type":"input"},{"id":"p4","name":"GND","x":0,"y":80,"type":"ground"},{"id":"p5","name":"2IN+","x":160,"y":20,"type":"input"},{"id":"p6","name":"2IN-","x":160,"y":40,"type":"input"},{"id":"p7","name":"2OUT","x":160,"y":60,"type":"output"},{"id":"p8","name":"VCC","x":160,"y":80,"type":"power"}]$json$, $json${"type":"LM393","family":"comparator","supply":"2 V to 36 V","rating":"Open-collector outputs — a pull-up resistor is required to get a high level","package":"SOIC-8 / PDIP-8","footprint":"SOIC-8"}$json$, null, $seed$Two independent comparators with the same input order as the LM358 and GND/VCC on pins 4 and 8. Outputs sink current; they never source.$seed$, $seed$Texas Instruments$seed$, $seed$LM393$seed$, $seed$https://www.ti.com/lit/ds/symlink/lm393.pdf$seed$, $json$["comparator","soic-8 / pdip-8","lm393"]$json$),
  ($seed$amplifier$seed$, $seed$TLV3501 Fast comparator with shutdown$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"-IN","x":0,"y":20,"type":"input"},{"id":"p2","name":"V-","x":0,"y":40,"type":"ground"},{"id":"p3","name":"+IN","x":0,"y":60,"type":"input"},{"id":"p4","name":"V+","x":160,"y":20,"type":"power"},{"id":"p5","name":"OUT","x":160,"y":40,"type":"output"},{"id":"p6","name":"SHDN","x":160,"y":60,"type":"input"}]$json$, $json${"type":"TLV3501","family":"comparator","supply":"Single supply, per the datasheet recommended-conditions table","rating":"Disabled when SHDN is within 0.9 V of V+; enabled at 1.7 V or more below it","package":"SOT-23-6 (DBV)","footprint":"SOT-23-6"}$json$, null, $seed$Nano-second comparator for zero-crossing and threshold detection, with a SHDN pin that idles the output stage.$seed$, $seed$Texas Instruments$seed$, $seed$TLV3501$seed$, $seed$https://www.ti.com/lit/ds/symlink/tlv3501.pdf$seed$, $json$["comparator","sot-23-6 (dbv)","tlv3501"]$json$),
  ($seed$converter$seed$, $seed$ADS1115 16-bit I2C ADC with PGA$seed$, true, $json${"width":160,"height":120,"paths":["M 0,0 L 160,0 L 160,120 L 0,120 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"ADDR","x":0,"y":20,"type":"input"},{"id":"p2","name":"ALERT/RDY","x":0,"y":40,"type":"output"},{"id":"p3","name":"GND","x":0,"y":60,"type":"ground"},{"id":"p4","name":"AIN0","x":0,"y":80,"type":"input"},{"id":"p5","name":"AIN1","x":0,"y":100,"type":"input"},{"id":"p6","name":"AIN2","x":160,"y":20,"type":"input"},{"id":"p7","name":"AIN3","x":160,"y":40,"type":"input"},{"id":"p8","name":"VDD","x":160,"y":60,"type":"power"},{"id":"p9","name":"SDA","x":160,"y":80,"type":"io"},{"id":"p10","name":"SCL","x":160,"y":100,"type":"input"}]$json$, $json${"type":"ADS1115","family":"adc","supply":"2.0 V to 5.5 V","rating":"16-bit, 4 inputs through a differential mux, 8-860 SPS, four I2C addresses via ADDR","package":"VSSOP-10 (DGS)","footprint":"VSSOP-10"}$json$, null, $seed$The go-to precision ADC for slow analog: AIN0-AIN3 on pins 4-7, ADDR picks one of four I2C addresses, and the open-drain ALERT/RDY doubles as a conversion-done interrupt.$seed$, $seed$Texas Instruments$seed$, $seed$ADS1115$seed$, $seed$https://www.ti.com/lit/ds/symlink/ads1115.pdf$seed$, $json$["adc","vssop-10 (dgs)","ads1115"]$json$),
  ($seed$converter$seed$, $seed$DAC8564 Quad 16-bit SPI DAC$seed$, true, $json${"width":160,"height":180,"paths":["M 0,0 L 160,0 L 160,180 L 0,180 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"VOUTA","x":0,"y":20,"type":"output"},{"id":"p2","name":"VOUTB","x":0,"y":40,"type":"output"},{"id":"p3","name":"VREFH/VREFOUT","x":0,"y":60,"type":"power"},{"id":"p4","name":"AVDD","x":0,"y":80,"type":"power"},{"id":"p5","name":"VREFL","x":0,"y":100,"type":"power"},{"id":"p6","name":"GND","x":0,"y":120,"type":"ground"},{"id":"p7","name":"VOUTC","x":0,"y":140,"type":"output"},{"id":"p8","name":"VOUTD","x":0,"y":160,"type":"output"},{"id":"p9","name":"SYNC","x":160,"y":20,"type":"input"},{"id":"p10","name":"SCLK","x":160,"y":40,"type":"input"},{"id":"p11","name":"DIN","x":160,"y":60,"type":"input"},{"id":"p12","name":"IOVDD","x":160,"y":80,"type":"power"},{"id":"p13","name":"A0","x":160,"y":100,"type":"input"},{"id":"p14","name":"A1","x":160,"y":120,"type":"input"},{"id":"p15","name":"ENABLE","x":160,"y":140,"type":"input"},{"id":"p16","name":"LDAC","x":160,"y":160,"type":"input"}]$json$, $json${"type":"DAC8564","family":"dac","supply":"2.7 V to 5.5 V","rating":"Four 16-bit channels, internal 2.5 V reference, 10 µs settling to ±0.003% FSR","package":"TSSOP-16 (PW)","footprint":"TSSOP-16"}$json$, null, $seed$Simultaneous-update quad DAC for set-point and waveform generation. LDAC (16) and ENABLE (15) are active-low, and A0/A1 address daisy-chained parts.$seed$, $seed$Texas Instruments$seed$, $seed$DAC8564$seed$, $seed$https://www.ti.com/lit/ds/symlink/dac8564.pdf$seed$, $json$["dac","tssop-16 (pw)","dac8564"]$json$),
  ($seed$converter$seed$, $seed$MCP4725A0T-E/CH 12-bit I2C DAC with EEPROM$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"VOUT","x":0,"y":20,"type":"output"},{"id":"p2","name":"VSS","x":0,"y":40,"type":"ground"},{"id":"p3","name":"VDD","x":0,"y":60,"type":"power"},{"id":"p4","name":"SDA","x":160,"y":20,"type":"io"},{"id":"p5","name":"SCL","x":160,"y":40,"type":"input"},{"id":"p6","name":"A0","x":160,"y":60,"type":"input"}]$json$, $json${"type":"MCP4725A0T-E/CH","family":"dac","supply":"2.7 V to 5.5 V","rating":"12-bit buffered output, rail-to-rail, VDD doubles as the reference; setting survives power-off","package":"SOT-23-6 (CH)","footprint":"SOT-23-6"}$json$, null, $seed$Single-channel trim DAC in six pins. The VDD rail is the reference, so a noisy supply is an output error; A0 selects one of eight I2C addresses.$seed$, $seed$Microchip Technology$seed$, $seed$MCP4725A0T-E/CH$seed$, $seed$https://ww1.microchip.com/downloads/en/DeviceDoc/22039d.pdf$seed$, $json$["dac","sot-23-6 (ch)","mcp4725a0t-e/ch"]$json$),
  ($seed$reference$seed$, $seed$REF3025AIDBZT 2.5 V precision reference$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"IN","x":0,"y":20,"type":"power"},{"id":"p2","name":"OUT","x":0,"y":40,"type":"power"},{"id":"p3","name":"GND","x":160,"y":20,"type":"ground"}]$json$, $json${"type":"REF3025AIDBZT","family":"voltage-reference","supply":"Up to 7 V input-to-ground","rating":"2.5 V ±0.2% initial accuracy, 75 ppm/°C max, 42 µA typical quiescent","package":"SOT-23-3 (DBZ)","footprint":"SOT-23-3"}$json$, null, $seed$Low-dropout series reference for ADC full-scale and DAC range. Three pins only: IN, OUT, GND.$seed$, $seed$Texas Instruments$seed$, $seed$REF3025AIDBZT$seed$, $seed$https://www.ti.com/lit/ds/symlink/ref30.pdf$seed$, $json$["voltage-reference","sot-23-3 (dbz)","ref3025aidbzt"]$json$),
  ($seed$reference$seed$, $seed$REF3033AIDBZR 3.3 V precision reference$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"IN","x":0,"y":20,"type":"power"},{"id":"p2","name":"OUT","x":0,"y":40,"type":"power"},{"id":"p3","name":"GND","x":160,"y":20,"type":"ground"}]$json$, $json${"type":"REF3033AIDBZR","family":"voltage-reference","supply":"Up to 7 V input-to-ground","rating":"3.3 V (3.2967-3.3033 V), 42 µA typical quiescent, 70 mA output short-circuit limit","package":"SOT-23-3 (DBZ)","footprint":"SOT-23-3"}$json$, null, $seed$Series reference for 3.3 V rails and sensor excitation. The absolute maximum on IN is only 7 V, so it cannot sit straight on an unregulated bus.$seed$, $seed$Texas Instruments$seed$, $seed$REF3033AIDBZR$seed$, $seed$https://www.ti.com/lit/ds/symlink/ref30.pdf$seed$, $json$["voltage-reference","sot-23-3 (dbz)","ref3033aidbzr"]$json$),
  ($seed$reference$seed$, $seed$TL431ACDBZR Programmable shunt reference$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"CATHODE","x":0,"y":20,"type":"io"},{"id":"p2","name":"REF","x":0,"y":40,"type":"input"},{"id":"p3","name":"ANODE","x":160,"y":20,"type":"power"}]$json$, $json${"type":"TL431ACDBZR","family":"voltage-reference","supply":"Cathode 3 V to 36 V, biased at 10 mA","rating":"V(ref) 2.495 V typical; shunt device, not a supply — it sinks current to hold a voltage","package":"SOT-23-3 (DBZ)","footprint":"SOT-23-3"}$json$, null, $seed$The error amplifier and set point inside most flyback and linear supplies, and a precision 2.5 V Zener substitute. In SOT-23-5 the same part is CATHODE 3 / REF 4 / ANODE 5, so the package decides the footprint.$seed$, $seed$Texas Instruments$seed$, $seed$TL431ACDBZR$seed$, $seed$https://www.ti.com/lit/ds/symlink/tl431.pdf$seed$, $json$["voltage-reference","sot-23-3 (dbz)","tl431acdbzr"]$json$),
  ($seed$regulator$seed$, $seed$LM7805 5 V 3-terminal positive regulator$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"INPUT","x":0,"y":20,"type":"input"},{"id":"p2","name":"GND","x":0,"y":40,"type":"ground"},{"id":"p3","name":"OUTPUT","x":160,"y":20,"type":"output"}]$json$, $json${"type":"LM7805","family":"fixed-regulator","vout":"5 V","iout":"1.5A","vinMax":"35V","rating":"Quiescent current 8 mA max; about 2 V dropout at 1 A, so the input needs roughly 7 V for a regulated 5 V","spice":"LM7805","package":"TO-220 (NDE)","footprint":"TO-220"}$json$, null, $seed$Fixed monolithic regulator with current limit and thermal shutdown in three pins, the LM340/LM78xx family document being the source of this table.$seed$, $seed$Texas Instruments$seed$, $seed$LM7805$seed$, $seed$https://www.ti.com/lit/ds/symlink/lm340.pdf$seed$, $json$["fixed-regulator","to-220 (nde)","lm7805"]$json$),
  ($seed$regulator$seed$, $seed$LM7812 12 V 3-terminal positive regulator$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"INPUT","x":0,"y":20,"type":"input"},{"id":"p2","name":"GND","x":0,"y":40,"type":"ground"},{"id":"p3","name":"OUTPUT","x":160,"y":20,"type":"output"}]$json$, $json${"type":"LM7812","family":"fixed-regulator","vout":"12 V","iout":"1.5A","vinMax":"35V","rating":"Quiescent current 8 mA max; about 2 V dropout at 1 A, so the input needs roughly 7 V for a regulated 5 V","package":"TO-220 (NDE)","footprint":"TO-220"}$json$, null, $seed$Fixed monolithic regulator with current limit and thermal shutdown in three pins, the LM340/LM78xx family document being the source of this table.$seed$, $seed$Texas Instruments$seed$, $seed$LM7812$seed$, $seed$https://www.ti.com/lit/ds/symlink/lm340.pdf$seed$, $json$["fixed-regulator","to-220 (nde)","lm7812"]$json$),
  ($seed$regulator$seed$, $seed$LM317T Adjustable positive regulator$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"ADJUST","x":0,"y":20,"type":"input"},{"id":"p2","name":"OUTPUT","x":0,"y":40,"type":"output"},{"id":"p3","name":"INPUT","x":160,"y":20,"type":"input"}]$json$, $json${"type":"LM317T","family":"adjustable-regulator","vout":"1.25 V to 37 V","iout":"1.5A","vinMax":"40V","rating":"Sets with two resistors; 65 dB typical ripple rejection; input-to-output differential up to 40 V","spice":"LM317","package":"TO-220 (KCS/KCT)","footprint":"TO-220"}$json$, null, $seed$Three-terminal adjustable regulator. The tab is the output, not ground, so an isolated mounting kit is required on a grounded heatsink.$seed$, $seed$Texas Instruments$seed$, $seed$LM317T$seed$, $seed$https://www.ti.com/lit/ds/symlink/lm317.pdf$seed$, $json$["adjustable-regulator","to-220 (kcs/kct)","lm317t"]$json$),
  ($seed$regulator$seed$, $seed$LM317MPX Adjustable regulator, SOT-223$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"ADJUST","x":0,"y":20,"type":"input"},{"id":"p2","name":"OUTPUT","x":0,"y":40,"type":"output"},{"id":"p3","name":"INPUT","x":160,"y":20,"type":"input"},{"id":"p4","name":"OUTPUT","x":160,"y":40,"type":"power"}]$json$, $json${"type":"LM317MPX","family":"adjustable-regulator","vout":"1.25 V to 37 V","iout":"1.5A","vinMax":"40V","rating":"Pin 4 is the package tab, internally tied to OUTPUT","spice":"LM317","package":"SOT-223 (DCY, 4-pin)","footprint":"SOT-223"}$json$, null, $seed$The surface-mount LM317. Four pads, not three: the datasheet pin table lists OUTPUT on pin 2 and the tab, which is where the heat leaves the part.$seed$, $seed$Texas Instruments$seed$, $seed$LM317MPX$seed$, $seed$https://www.ti.com/lit/ds/symlink/lm317.pdf$seed$, $json$["adjustable-regulator","sot-223 (dcy, 4-pin)","lm317mpx"]$json$),
  ($seed$regulator$seed$, $seed$AMS1117-3.3 3.3 V 1 A low-dropout regulator$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"GROUND","x":0,"y":20,"type":"power"},{"id":"p2","name":"VOUT","x":0,"y":40,"type":"output"},{"id":"p3","name":"VIN","x":160,"y":20,"type":"input"}]$json$, $json${"type":"AMS1117-3.3","family":"ldo","vout":"3.3 V ±1.5%","iout":"1A","vinMax":"15V","rating":"Dropout 1.1 V typical / 1.3 V max at 0.8 A","package":"SOT-223","footprint":"SOT-223"}$json$, null, $seed$Fixed 3.3 V LDO. Pin 1 is ground on the fixed part and adjust on the adjustable AMS1117, so the suffix decides what that pad does.$seed$, $seed$Advanced Monolithic Systems$seed$, $seed$AMS1117-3.3$seed$, $seed$http://www.advanced-monolithic.com/pdf/ds1117.pdf$seed$, $json$["ldo","sot-223","ams1117-3.3"]$json$),
  ($seed$regulator$seed$, $seed$TPS7A4700RGWR 1 A low-noise high-PSRR LDO$seed$, true, $json${"width":160,"height":220,"paths":["M 0,0 L 160,0 L 160,220 L 0,220 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"OUT","x":0,"y":20,"type":"output"},{"id":"p2","name":"OUT","x":0,"y":40,"type":"output"},{"id":"p3","name":"SENSE/FB","x":0,"y":60,"type":"input"},{"id":"p4","name":"6P4V2","x":0,"y":80,"type":"passive"},{"id":"p5","name":"6P4V1","x":0,"y":100,"type":"passive"},{"id":"p6","name":"3P2V","x":0,"y":120,"type":"passive"},{"id":"p7","name":"GND","x":0,"y":140,"type":"ground"},{"id":"p8","name":"1P6V","x":0,"y":160,"type":"passive"},{"id":"p9","name":"0P8V","x":0,"y":180,"type":"passive"},{"id":"p10","name":"0P4V","x":0,"y":200,"type":"passive"},{"id":"p11","name":"0P2V","x":160,"y":20,"type":"passive"},{"id":"p12","name":"0P1V","x":160,"y":40,"type":"passive"},{"id":"p13","name":"EN","x":160,"y":60,"type":"input"},{"id":"p14","name":"NR","x":160,"y":80,"type":"input"},{"id":"p15","name":"IN","x":160,"y":100,"type":"power"},{"id":"p16","name":"IN","x":160,"y":120,"type":"power"},{"id":"p17","name":"NC","x":160,"y":140,"type":"passive"},{"id":"p18","name":"NC","x":160,"y":160,"type":"passive"},{"id":"p19","name":"NC","x":160,"y":180,"type":"passive"},{"id":"p20","name":"OUT","x":160,"y":200,"type":"output"}]$json$, $json${"type":"TPS7A4700RGWR","family":"ldo","vout":"1.4 V to 20.5 V (TPS7A4701: to 34 V)","iout":"1A","vinMax":"36V","rating":"ANY-OUT pins 8-12 tie to ground to add fixed offsets; the exposed pad is ground","package":"VQFN-20 (RGW), 5x5 mm","footprint":"VQFN-20"}$json$, null, $seed$High-PSRR bipolar LDO for clean analog and RF rails. This revision of the document packages the part only as the 20-lead VQFN, so any older 8-pin footprint in a library is describing a different variant.$seed$, $seed$Texas Instruments$seed$, $seed$TPS7A4700RGWR$seed$, $seed$https://www.ti.com/lit/ds/symlink/tps7a47.pdf$seed$, $json$["ldo","vqfn-20 (rgw), 5x5 mm","tps7a4700rgwr"]$json$),
  ($seed$regulator$seed$, $seed$TPS54331DR 3 A step-down converter$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"BOOT","x":0,"y":20,"type":"output"},{"id":"p2","name":"VIN","x":0,"y":40,"type":"power"},{"id":"p3","name":"EN","x":0,"y":60,"type":"input"},{"id":"p4","name":"SS","x":0,"y":80,"type":"input"},{"id":"p5","name":"VSENSE","x":160,"y":20,"type":"input"},{"id":"p6","name":"COMP","x":160,"y":40,"type":"output"},{"id":"p7","name":"GND","x":160,"y":60,"type":"ground"},{"id":"p8","name":"PH","x":160,"y":80,"type":"output"}]$json$, $json${"type":"TPS54331DR","family":"buck-converter","vout":"Adjustable down to 0.8 V","iout":"3A","vinMax":"28V","rating":"573 kHz, cycle-by-cycle current limit, pulse-skipping Eco-mode; EN floating = enabled","package":"SOIC-8 (DD)","footprint":"SOIC-8"}$json$, null, $seed$Bootstrap-driven buck regulator with soft start on SS and the feedback divider landing on VSENSE. Pin 8 PH is the switching node — keep that copper small.$seed$, $seed$Texas Instruments$seed$, $seed$TPS54331DR$seed$, $seed$https://www.ti.com/lit/ds/symlink/tps54331.pdf$seed$, $json$["buck-converter","soic-8 (dd)","tps54331dr"]$json$),
  ($seed$regulator$seed$, $seed$TPS5430DDA 3 A wide-VIN step-down converter$seed$, true, $json${"width":160,"height":120,"paths":["M 0,0 L 160,0 L 160,120 L 0,120 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"BOOT","x":0,"y":20,"type":"output"},{"id":"p2","name":"NC","x":0,"y":40,"type":"passive"},{"id":"p3","name":"NC","x":0,"y":60,"type":"passive"},{"id":"p4","name":"VSENSE","x":0,"y":80,"type":"input"},{"id":"p5","name":"ENA","x":0,"y":100,"type":"input"},{"id":"p6","name":"GND","x":160,"y":20,"type":"ground"},{"id":"p7","name":"VIN","x":160,"y":40,"type":"power"},{"id":"p8","name":"PH","x":160,"y":60,"type":"output"},{"id":"p9","name":"DAP","x":160,"y":80,"type":"power"}]$json$, $json${"type":"TPS5430DDA","family":"buck-converter","vout":"0.802 V reference, adjustable","iout":"3A","vinMax":"36V","rating":"573 kHz; the datasheet recommends a 5.5 V to 36 V input for this ordering","package":"HSOIC-8 with PowerPAD (DDA)","footprint":"HSOIC-8"}$json$, null, $seed$Higher-voltage buck cousin of the TPS54331 with a different pin map: two no-connect pins, enable on 5, and pin 9 the exposed pad that must join ground.$seed$, $seed$Texas Instruments$seed$, $seed$TPS5430DDA$seed$, $seed$https://www.ti.com/lit/ds/symlink/tps5430.pdf$seed$, $json$["buck-converter","hsoic-8 with powerpad (dda)","tps5430dda"]$json$),
  ($seed$sensor$seed$, $seed$BME280 Humidity, pressure and temperature sensor$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"GND","x":0,"y":20,"type":"ground"},{"id":"p2","name":"CSB","x":0,"y":40,"type":"input"},{"id":"p3","name":"SDI","x":0,"y":60,"type":"io"},{"id":"p4","name":"SCK","x":0,"y":80,"type":"input"},{"id":"p5","name":"SDO","x":160,"y":20,"type":"io"},{"id":"p6","name":"VDDIO","x":160,"y":40,"type":"power"},{"id":"p7","name":"GND","x":160,"y":60,"type":"ground"},{"id":"p8","name":"VDD","x":160,"y":80,"type":"power"}]$json$, $json${"type":"BME280","family":"environmental","interface":"I2C / SPI","supply":"VDD 1.71 V to 3.6 V; VDDIO 1.2 V to 3.6 V","rating":"Pressure 300–1100 hPa, ±1 hPa absolute; temperature −40…+85 °C, ±0.5 °C at 25 °C; I2C address 0x76 or 0x77 from SDO","package":"LGA-8, 2.5 × 2.5 × 0.93 mm","footprint":"LGA-8"}$json$, null, $seed$4-in-1 environmental sensor on I2C or SPI. CSB low selects I2C, high selects SPI; SDO sets the I2C address.$seed$, $seed$Bosch Sensortec$seed$, $seed$BME280$seed$, $seed$https://www.bosch-sensortec.com/media/boschsensortec/downloads/datasheets/bst-bme280-ds002.pdf$seed$, $json$["environmental","i2c / spi","bme280"]$json$),
  ($seed$sensor$seed$, $seed$BMP280 Absolute barometric pressure sensor$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"GND","x":0,"y":20,"type":"ground"},{"id":"p2","name":"CSB","x":0,"y":40,"type":"input"},{"id":"p3","name":"SDI","x":0,"y":60,"type":"io"},{"id":"p4","name":"SCK","x":0,"y":80,"type":"input"},{"id":"p5","name":"SDO","x":160,"y":20,"type":"io"},{"id":"p6","name":"VDDIO","x":160,"y":40,"type":"power"},{"id":"p7","name":"GND","x":160,"y":60,"type":"ground"},{"id":"p8","name":"VDD","x":160,"y":80,"type":"power"}]$json$, $json${"type":"BMP280","family":"pressure","interface":"I2C / SPI","supply":"VDD 1.71 V to 3.6 V; VDDIO 1.2 V to 3.6 V","rating":"Pressure 300–1100 hPa; 2.7 µA at 1 Hz forced mode; I2C address 0x76 or 0x77 from SDO","package":"LGA-8, 2.0 × 2.5 × 0.95 mm","footprint":"LGA-8"}$json$, null, $seed$Barometric pressure on I2C or SPI, register and performance compatible with the BME280, so one footprint serves both.$seed$, $seed$Bosch Sensortec$seed$, $seed$BMP280$seed$, $seed$https://www.bosch-sensortec.com/media/boschsensortec/downloads/datasheets/bst-bmp280-ds001.pdf$seed$, $json$["pressure","i2c / spi","bmp280"]$json$),
  ($seed$sensor$seed$, $seed$BME680 Gas, humidity, pressure and temperature sensor$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"GND","x":0,"y":20,"type":"ground"},{"id":"p2","name":"CSB","x":0,"y":40,"type":"input"},{"id":"p3","name":"SDI","x":0,"y":60,"type":"io"},{"id":"p4","name":"SCK","x":0,"y":80,"type":"input"},{"id":"p5","name":"SDO","x":160,"y":20,"type":"io"},{"id":"p6","name":"VDDIO","x":160,"y":40,"type":"power"},{"id":"p7","name":"GND","x":160,"y":60,"type":"ground"},{"id":"p8","name":"VDD","x":160,"y":80,"type":"power"}]$json$, $json${"type":"BME680","family":"environmental","interface":"I2C / SPI","supply":"VDD 1.71 V to 3.6 V; VDDIO 1.2 V to 3.6 V","rating":"MOX gas sensor plus humidity, pressure and temperature; optimized for 1.8 V; vent hole needs open air flow","package":"LGA-8, 3.0 × 3.0 × 1.00 mm","footprint":"LGA-8"}$json$, null, $seed$4-in-1 air-quality sensor. Same CSB/SDI/SCK/SDO SPI-4W, SPI-3W and I2C connection options as the BME280.$seed$, $seed$Bosch Sensortec$seed$, $seed$BME680$seed$, $seed$https://www.bosch-sensortec.com/media/boschsensortec/downloads/datasheets/bst-bme680-ds001.pdf$seed$, $json$["environmental","i2c / spi","bme680"]$json$),
  ($seed$sensor$seed$, $seed$SHT40 Humidity and temperature sensor with heater$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"SDA","x":0,"y":20,"type":"io"},{"id":"p2","name":"SCL","x":0,"y":40,"type":"input"},{"id":"p3","name":"VDD","x":160,"y":20,"type":"power"},{"id":"p4","name":"VSS","x":160,"y":40,"type":"ground"}]$json$, $json${"type":"SHT40","family":"humidity","interface":"I2C","supply":"VDD 1.08 V to 3.6 V","rating":"Two-wire I2C only; on-board heater; die pad is not connected to any pin","package":"DFN-4, open cavity","footprint":"DFN-4"}$json$, null, $seed$SHT4x family in a 4-pin DFN: SDA on 1, SCL on 2, VDD on 3, VSS on 4. No copper under the sensor except the pin pads.$seed$, $seed$Sensirion$seed$, $seed$SHT40$seed$, $seed$https://sensirion.com/media/documents/33FD6951/6555C40E/Sensirion_Datasheet_SHT4x.pdf$seed$, $json$["humidity","i2c","sht40"]$json$),
  ($seed$sensor$seed$, $seed$VEML6040 RGB colour light sensor$seed$, true, $json${"width":160,"height":100,"paths":["M 0,0 L 160,0 L 160,100 L 0,100 Z"],"circles":[{"cx":80,"cy":10,"r":4}]}$json$, $json$[{"id":"p1","name":"GND","x":0,"y":20,"type":"ground"},{"id":"p2","name":"SDAT","x":0,"y":40,"type":"io"},{"id":"p3","name":"SCLK","x":160,"y":20,"type":"input"},{"id":"p4","name":"VDD","x":160,"y":40,"type":"power"}]$json$, $json${"type":"VEML6040","family":"color-light","interface":"I2C","supply":"VDD 2.5 V to 3.6 V","rating":"Red, green, blue and clear channels, 16-bit each, 0.007865 lux per step","package":"OPLGA-4, 2.0 × 1.25 × 1.0 mm","footprint":"OPLGA-4"}$json$, null, $seed$I2C colour sensor: GND on 1, SDAT (open-drain data) on 2, SCLK on 3, VDD on 4, with 16-bit registers read a word at a time.$seed$, $seed$Vishay$seed$, $seed$VEML6040$seed$, $seed$https://www.vishay.com/docs/84276/veml6040.pdf$seed$, $json$["color-light","i2c","veml6040"]$json$),
